var i=`0490-kibbeh-bil-sanieh`;var t=`world-0490`;var o=`SY`;var r=`western-asia`;var a=4;var l=80;var g={en:`Kibbeh Bil Sanieh`,ua:`Запечене кіббе`};var s={en:`A traditional dish from Syria, centered on bulgur, ground lamb, yellow onion, pine nut. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Сирія. Основні складники: булгур, фарш з ягнятини, жовта цибуля, кедровий горіх. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Cook the listed ingredients in simmering water for about 13 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 13 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:13,i:[[`bulgur`,300,`g`],[`water`,360,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-lamb`,600,`g`],[`yellow-onion`,230,`g`],[`pine-nut`,70,`g`],[`allspice-berries`,4,`g`],[`ground-cinnamon`,3,`g`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:17,i:[[`extra-virgin-olive-oil`,40,`ml`]]},{en:`Bake in a preheated 180°C oven for about 38 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 38 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:38,i:[]}];var d={slug:i,id:t,country:`SY`,region:r,servings:4,minutes:80,title:g,text:s,steps:u};export{o as country,d as default,t as id,l as minutes,r as region,a as servings,i as slug,u as steps,s as text,g as title};